public class SubstringCounter {

    public static int countOccurrences(String s, String sub) {
        if (sub.isEmpty()) {
            return 0;
        }
        int count = 0;
        int from = 0;
        while (true) {
            int found = s.indexOf(sub, from);
            if (found == -1) {
                break;
            }
            count++;
            from = found + sub.length();
        }
        return count;
    }
}
